```javascript
function validarCPF(cpf) {
    // Remover pontos e traço
    cpf = cpf.replace(/[.-]/g, '');

    // Verificar se o CPF tem 11 dígitos
    if (cpf.length !== 11) {
        return false;
    }

    // Verificar se o CPF é sequencial (ex: 11111111111)
    if (/^(.)\1{10}$/.test(cpf)) {
        return false;
    }

    // Calcular o primeiro dígito verificador
    let soma = 0;
    for (let i = 0; i < 9; i++) {
        soma += parseInt(cpf[i]) * (10 - i);
    }
    let dv1 = 11 - (soma % 11);
    if (dv1 === 10 || dv1 === 11) {
        dv1 = 0;
    }

    // Calcular o segundo dígito verificador
    soma = 0;
    for (let i = 0; i < 10; i++) {
        soma += parseInt(cpf[i]) * (11 - i);
    }
    let dv2 = 11 - (soma % 11);
    if (dv2 === 10 || dv2 === 11) {
        dv2 = 0;
    }

    // Verificar se os dígitos verificadores coincidem
    return parseInt(cpf[9]) === dv1 && parseInt(cpf[10]) === dv2;
}
