```javascript
function ordenar(lista) {
    if (lista.length <= 1) {
        return lista;
    }

    let pivot = lista[0];
    let menores = [];
    let maiores = [];

    for (let i = 1; i < lista.length; i++) {
        if (lista[i] <= pivot) {
            menores.push(lista[i]);
        } else {
            maiores.push(lista[i]);
        }
    }

    return ordenar(menores).concat([pivot], ordenar(maiores));
}
